const readline = require('readline');
const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

let lines = [];
rl.on('line', (line) => {
  lines.push(line);
  if (lines.length === 5) {
    const k = parseInt(lines[0]);
    const grid = lines.slice(1, 5);
    const times = {};
    for (let i = 0; i < 4; i++) {
      for (let j = 0; j < 4; j++) {
        const c = grid[i][j];
        if (c !== '.') {
          const t = parseInt(c);
          if (!times[t]) times[t] = [];
          times[t].push([i, j]);
        }
      }
    }
    let possible = true;
    for (const t in times) {
      if (times[t].length > 2 * k) {
        possible = false;
        break;
      }
    }
    console.log(possible ? 'YES' : 'NO');
    rl.close();
  }
});
