const readline = require('readline');

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

let input = [];
rl.on('line', (line) => {
  input.push(line);
});

rl.on('close', () => {
  const k = parseInt(input[0]);
  const grid = input.slice(1, 5);

  // Collect all required times
  const times = [];
  for (let i = 0; i < 4; i++) {
    for (let j = 0; j < 4; j++) {
      const c = grid[i][j];
      if (c !== '.') {
        times.push(parseInt(c));
      }
    }
  }

  // Group by time
  const timeCounts = {};
  for (const t of times) {
    timeCounts[t] = (timeCounts[t] || 0) + 1;
  }

  let possible = true;
  for (const t in timeCounts) {
    if (timeCounts[t] > 2 * k) {
      possible = false;
      break;
    }
  }

  console.log(possible ? 'YES' : 'NO');
});
